(function() {
    'use strict';

    class DemandForecastAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Demand Forecasting & Inventory Optimization';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    name: `Spring/Summer Y1 - Calibration`,
                    briefing: `Season 1: Spring/Summer \u2014 Calibration. Welcome to Moda Dinamica. You have MXN $18M for analytics transformation over 4 seasons. Configure your ML forecasting system, set your buying strategy, and establish initial inventory policies. Your baseline: 61% forecast accuracy, 28% markdown rate, 11% stockout rate, 48% gross margin.`
                },
                {
                    name: `Fall/Winter Y1 - Optimization`,
                    briefing: `Season 2: Fall/Winter \u2014 Optimization. Review Season 1 results and optimize. This season includes 45 new styles with no sales history. Your model now benefits from Season 1 learning data. Consider how to handle new product cold-start forecasting.`
                },
                {
                    name: `Spring/Summer Y2 - Crisis`,
                    briefing: `Season 3: Spring/Summer Year 2 \u2014 Crisis Response. ALERT: A major influencer with 4.2M followers posted wearing your Cascada Linen Set. Demand is spiking 12x above forecast. Teams with higher forecast investment detect this early. Additionally, your primary supplier has experienced delays. How do you respond?`
                },
                {
                    name: `Fall/Winter Y2 - Scale`,
                    briefing: `Season 4: Fall/Winter Year 2 \u2014 Scale and ROI. Final season. Your board expects a clear demonstration of analytics ROI. The CEO wants markdown rate below 18%, stockouts below 7%, and gross margin above 52%. Make your final investments count \u2014 this is your transformation scorecard.`
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    transformationBudget: 18000,
                    forecastAccuracy: 0.61,
                    grossMargin: 0.48,
                    markdownRate: 0.28,
                    stockoutRate: 0.11,
                    inventoryTurnover: 4.2,
                    cumulativeProfit: 0,
                    marginHistory: [],
                    accuracyHistory: [],
                    profitHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    forecastInvestment: 2000,
                    trendAllocation: 25,
                    safetyStockLevel: 130,
                    markdownWeek: 8
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var fiInput = document.getElementById('forecastInvestmentInput');
            if (fiInput) decisions.forecastInvestment = parseFloat(fiInput.value);

            var taInput = document.getElementById('trendAllocationInput');
            if (taInput) decisions.trendAllocation = parseInt(taInput.value);

            var ssInput = document.getElementById('safetyStockInput');
            if (ssInput) decisions.safetyStockLevel = parseInt(ssInput.value);

            var mwInput = document.getElementById('markdownWeekInput');
            if (mwInput) decisions.markdownWeek = parseInt(mwInput.value);

            if (!decisions.forecastInvestment && decisions.forecastInvestment !== 0 || decisions.forecastInvestment < 0 || decisions.forecastInvestment > 5000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('invest_warning'), 'warning'
                );
                return false;
            }

            var budgetRemaining = window.mySimulation.state.domainState.transformationBudget;
            if (decisions.forecastInvestment > budgetRemaining) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_exceeded'), 'warning'
                );
                return false;
            }

            if (!decisions.trendAllocation || decisions.trendAllocation < 15 || decisions.trendAllocation > 40) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('trend_warning'), 'warning'
                );
                return false;
            }

            if (!decisions.safetyStockLevel || decisions.safetyStockLevel < 100 || decisions.safetyStockLevel > 250) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('safety_warning'), 'warning'
                );
                return false;
            }

            if (!decisions.markdownWeek || decisions.markdownWeek < 6 || decisions.markdownWeek > 10) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('markdown_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            var forecastInvestment = d.forecastInvestment;
            var trendPct = d.trendAllocation / 100;
            var safetyMult = d.safetyStockLevel / 100;
            var mdWeek = d.markdownWeek;

            ds.transformationBudget -= forecastInvestment;

            var accuracyGain = Math.min(0.20, forecastInvestment / 25000);
            var learningBonus = (period - 1) * 0.02;
            var newAccuracy = Math.min(0.85, 0.61 + accuracyGain + learningBonus);
            ds.forecastAccuracy = newAccuracy;

            var safetyEffect = (safetyMult - 1.0) * 0.04;
            var accuracyEffect = (newAccuracy - 0.61) * 0.25;
            var newStockout = Math.max(0.03, 0.11 - safetyEffect - accuracyEffect);
            ds.stockoutRate = newStockout;

            var trendPenalty = (trendPct - 0.25) * 0.3;
            var markdownTimingEffect = (8 - mdWeek) * 0.015;
            var accuracyMdEffect = (newAccuracy - 0.61) * 0.4;
            var newMarkdown = Math.max(0.10, 0.28 - accuracyMdEffect - markdownTimingEffect + trendPenalty);
            ds.markdownRate = newMarkdown;

            var holdingCostPenalty = (safetyMult - 1.0) * 0.015;
            var earlyMdMarginCost = Math.max(0, (8 - mdWeek) * 0.005);
            var marginGain = (0.28 - newMarkdown) * 0.5;
            var newMargin = Math.min(0.58, 0.48 + marginGain - holdingCostPenalty - earlyMdMarginCost);
            ds.grossMargin = newMargin;

            var turnoverImprovement = (newAccuracy - 0.61) * 3.0 + (1.0 / safetyMult - 0.5) * 0.5;
            ds.inventoryTurnover = Math.min(7.5, 4.2 + turnoverImprovement);

            var baseRevenue = 350000;
            var stockoutLoss = baseRevenue * newStockout;
            var trendUpside = baseRevenue * trendPct * 0.15 * Math.max(0, newAccuracy / 0.61 - 1);
            var revenue = baseRevenue - stockoutLoss + trendUpside;

            if (period === 3) {
                var viralBonus = forecastInvestment > 3000 ? 8000 : 2000;
                revenue += viralBonus;
            }

            var profit = revenue * newMargin - forecastInvestment;
            ds.cumulativeProfit += profit;

            ds.marginHistory.push(Math.round(newMargin * 1000) / 10);
            ds.accuracyHistory.push(Math.round(newAccuracy * 1000) / 10);
            ds.profitHistory.push(Math.round(profit));

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
            }, 500);

            return {
                period: period,
                forecastInvestment: forecastInvestment,
                trendAllocation: d.trendAllocation,
                safetyStockLevel: d.safetyStockLevel,
                markdownWeek: mdWeek,
                forecastAccuracy: Math.round(newAccuracy * 1000) / 10,
                stockoutRate: Math.round(newStockout * 1000) / 10,
                markdownRate: Math.round(newMarkdown * 1000) / 10,
                grossMargin: Math.round(newMargin * 1000) / 10,
                inventoryTurnover: Math.round(ds.inventoryTurnover * 10) / 10,
                revenue: Math.round(revenue),
                profit: Math.round(profit),
                cumulativeProfit: Math.round(ds.cumulativeProfit),
                budgetRemaining: Math.round(ds.transformationBudget)
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.transformationBudget',
                (v) => '$' + Math.round(v).toLocaleString() + 'K');
            uiManager.bind('accuracyDisplay', 'domainState.forecastAccuracy',
                (v) => (v * 100).toFixed(1) + '%');
            uiManager.bind('marginDisplay', 'domainState.grossMargin',
                (v) => (v * 100).toFixed(1) + '%');
            uiManager.bind('stockoutDisplay', 'domainState.stockoutRate',
                (v) => (v * 100).toFixed(1) + '%');
            uiManager.bind('markdownDisplay', 'domainState.markdownRate',
                (v) => (v * 100).toFixed(1) + '%');
            uiManager.bind('profitDisplay', 'domainState.cumulativeProfit',
                (v) => '$' + Math.round(v).toLocaleString() + 'K');
        }

        getChartConfig() {
            return {
                marginChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Gross Margin (%)',
                            data: [],
                            borderColor: '#27ae60',
                            backgroundColor: 'rgba(39,174,96,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Gross Margin Trend' } },
                        scales: { y: { beginAtZero: false, min: 40, max: 60 } }
                    }
                },
                accuracyChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Forecast Accuracy - WAFA (%)',
                            data: [],
                            borderColor: '#2e86c1',
                            backgroundColor: 'rgba(46,134,193,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Forecast Accuracy (WAFA) Trend' } },
                        scales: { y: { beginAtZero: false, min: 50, max: 90 } }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.marginHistory.map(function(_, i) { return 'S' + (i + 1); });
            return {
                marginChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.marginHistory }]
                },
                accuracyChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.accuracyHistory }]
                }
            };
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.forecastInvestment', label: 'Invest (K)', i18nKey: 'col_investment', formatter: (v) => '$' + v.toLocaleString() },
                { key: 'results.trendAllocation', label: 'Trend %', i18nKey: 'col_trend' },
                { key: 'results.forecastAccuracy', label: 'WAFA %', i18nKey: 'col_accuracy' },
                { key: 'results.stockoutRate', label: 'Stockout %', i18nKey: 'col_stockout' },
                { key: 'results.markdownRate', label: 'Markdown %', i18nKey: 'col_markdown' },
                { key: 'results.grossMargin', label: 'Margin %', i18nKey: 'col_margin' },
                { key: 'results.profit', label: 'Profit (K)', i18nKey: 'col_profit', formatter: (v) => '$' + v.toLocaleString() }
            ];
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var finalMargin = (last.results && last.results.grossMargin) ? last.results.grossMargin / 100 : 0;
            var finalMarkdown = (last.results && last.results.markdownRate) ? last.results.markdownRate / 100 : 1;
            var finalStockout = (last.results && last.results.stockoutRate) ? last.results.stockoutRate / 100 : 1;
            var totalProfit = history.reduce(function(s, r) { return s + ((r.results && r.results.profit) || 0); }, 0);

            var performance = 'Needs Improvement';
            var insights = [];

            if (finalMargin >= 0.52 && finalMarkdown <= 0.18 && finalStockout <= 0.07) {
                performance = 'Excellent - Transformation Target Achieved';
                insights.push('All three transformation KPIs met: margin, markdown, and stockout targets achieved.');
                insights.push('The board will approve continued analytics investment based on these results.');
            } else if (finalMargin >= 0.50 || finalMarkdown <= 0.22) {
                performance = 'Good - Significant Progress';
                if (finalMargin >= 0.50) insights.push('Gross margin improved meaningfully from the 48% baseline.');
                if (finalMarkdown <= 0.22) insights.push('Markdown rate reduced significantly from the 28% baseline.');
                if (finalStockout > 0.07) insights.push('Stockout rate needs further improvement to reach the 7% target.');
            } else {
                insights.push('The analytics transformation has not yet delivered sufficient financial impact.');
                insights.push('Consider increasing forecast investment and optimizing the safety stock versus markdown trade-off.');
            }

            return {
                totalProfit: totalProfit,
                finalMargin: Math.round(finalMargin * 1000) / 10,
                finalMarkdown: Math.round(finalMarkdown * 1000) / 10,
                finalStockout: Math.round(finalStockout * 1000) / 10,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (state.currentPeriod === 3) {
                return window.mySimulation.t('hint_viral');
            }
            if (state.domainState.transformationBudget < 0) {
                return window.mySimulation.t('hint_budget_overrun');
            }
            if (results.stockoutRate > 9) {
                return window.mySimulation.t('hint_high_stockout');
            }
            if (results.markdownRate > 24) {
                return window.mySimulation.t('hint_high_markdown');
            }
            if (results.forecastAccuracy < 65) {
                return window.mySimulation.t('hint_low_accuracy');
            }
            if (results.grossMargin > 51) {
                return window.mySimulation.t('hint_good_margin');
            }
            return null;
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:                   `Demand Forecasting & Inventory Optimization`,
                    subtitle:                `Moda Dinamica S.A. — Analytics Transformation Program`,
                    period_label:            `Season`,
                    period_of:               `of`,
                    briefing_heading:        `Season Briefing`,
                    budget_label:            `Transformation Budget`,
                    accuracy_label:          `Forecast Accuracy (WAFA)`,
                    margin_label:            `Gross Margin`,
                    stockout_label:          `Stockout Rate`,
                    markdown_label:          `Markdown Rate`,
                    profit_label:            `Cumulative Profit`,
                    decisions_heading:       `Season Decisions`,
                    forecast_invest_label:   `ML Forecast Investment (thousands MXN)`,
                    forecast_invest_hint:    `Budget for data sources, model training, and feature engineering (0 - 5,000K)`,
                    trend_alloc_label:       `Trend Item Allocation (%)`,
                    trend_alloc_hint:        `Percentage of buying budget for high-risk trend/AZ items (15% - 40%)`,
                    safety_stock_label:      `Safety Stock Multiplier (x100)`,
                    safety_stock_hint:       `100 = 1.0x baseline, 165 = 1.65x for 95% service level (100 - 250)`,
                    markdown_week_label:     `Markdown Trigger Week`,
                    markdown_week_hint:      `Week to trigger markdowns on slow sellers (6 = aggressive, 10 = late)`,
                    submit_btn:              `Submit Season`,
                    undo_btn:                `Undo Last Season`,
                    history_heading:         `Season History`,
                    invest_warning:          `Investment must be between 0 and 5,000 (thousands MXN)`,
                    budget_exceeded:         `Investment exceeds remaining transformation budget`,
                    trend_warning:           `Trend allocation must be between 15% and 40%`,
                    safety_warning:          `Safety stock multiplier must be between 100 and 250`,
                    markdown_warning:        `Markdown trigger week must be between 6 and 10`,
                    hint_viral:              `Viral event detected! Higher forecast investment helps detect demand surges earlier and capture more revenue.`,
                    hint_budget_overrun:     `Warning: Transformation budget is overrun. Future investments are limited.`,
                    hint_high_stockout:      `Stockout rate is above 9%. Consider increasing safety stock levels or investing more in forecast accuracy.`,
                    hint_high_markdown:      `Markdown rate is above 24%. Consider adjusting markdown timing or reducing trend allocation.`,
                    hint_low_accuracy:       `Forecast accuracy is below 65%. Investing more in ML features and data sources will improve all downstream metrics.`,
                    hint_good_margin:        `Strong margin performance! You are on track toward the 52% target.`,
                    col_investment:          `Investment (K)`,
                    col_trend:               `Trend %`,
                    col_accuracy:            `WAFA %`,
                    col_stockout:            `Stockout %`,
                    col_markdown:            `Markdown %`,
                    col_margin:              `Margin %`,
                    col_profit:              `Profit (K)`
                },
                es: {
                    title:                   `Pronostico de Demanda y Optimizacion de Inventario`,
                    subtitle:                `Moda Dinamica S.A. — Programa de Transformacion Analitica`,
                    period_label:            `Temporada`,
                    period_of:               `de`,
                    briefing_heading:        `Resumen de Temporada`,
                    budget_label:            `Presupuesto de Transformacion`,
                    accuracy_label:          `Precision del Pronostico (WAFA)`,
                    margin_label:            `Margen Bruto`,
                    stockout_label:          `Tasa de Desabasto`,
                    markdown_label:          `Tasa de Rebajas`,
                    profit_label:            `Beneficio Acumulado`,
                    decisions_heading:       `Decisiones de Temporada`,
                    forecast_invest_label:   `Inversion en Pronostico ML (miles MXN)`,
                    forecast_invest_hint:    `Presupuesto para fuentes de datos, entrenamiento de modelos e ingenieria de features (0 - 5,000K)`,
                    trend_alloc_label:       `Asignacion a Productos de Tendencia (%)`,
                    trend_alloc_hint:        `Porcentaje del presupuesto de compra para articulos de alto riesgo/AZ (15% - 40%)`,
                    safety_stock_label:      `Multiplicador de Stock de Seguridad (x100)`,
                    safety_stock_hint:       `100 = 1.0x linea base, 165 = 1.65x para nivel de servicio 95% (100 - 250)`,
                    markdown_week_label:     `Semana de Activacion de Rebajas`,
                    markdown_week_hint:      `Semana para activar rebajas en productos de baja rotacion (6 = agresivo, 10 = tardio)`,
                    submit_btn:              `Enviar Temporada`,
                    undo_btn:                `Deshacer Ultima Temporada`,
                    history_heading:         `Historial de Temporadas`,
                    invest_warning:          `La inversion debe estar entre 0 y 5,000 (miles MXN)`,
                    budget_exceeded:         `La inversion excede el presupuesto de transformacion restante`,
                    trend_warning:           `La asignacion de tendencia debe estar entre 15% y 40%`,
                    safety_warning:          `El multiplicador de stock de seguridad debe estar entre 100 y 250`,
                    markdown_warning:        `La semana de activacion de rebajas debe estar entre 6 y 10`,
                    hint_viral:              `Evento viral detectado! Mayor inversion en pronostico ayuda a detectar picos de demanda y capturar mas ingresos.`,
                    hint_budget_overrun:     `Advertencia: El presupuesto de transformacion se ha agotado. Las inversiones futuras estan limitadas.`,
                    hint_high_stockout:      `La tasa de desabasto supera el 9%. Considere aumentar los niveles de stock de seguridad o invertir mas en precision del pronostico.`,
                    hint_high_markdown:      `La tasa de rebajas supera el 24%. Considere ajustar el momento de las rebajas o reducir la asignacion a tendencias.`,
                    hint_low_accuracy:       `La precision del pronostico esta por debajo del 65%. Invertir mas en features de ML y fuentes de datos mejorara todas las metricas.`,
                    hint_good_margin:        `Excelente desempeno de margen! Esta en camino hacia el objetivo del 52%.`,
                    col_investment:          `Inversion (K)`,
                    col_trend:               `Tendencia %`,
                    col_accuracy:            `WAFA %`,
                    col_stockout:            `Desabasto %`,
                    col_markdown:            `Rebajas %`,
                    col_margin:              `Margen %`,
                    col_profit:              `Beneficio (K)`
                }
            };
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            if (idx < 0) idx = 0;
            var round = this.ROUNDS[idx];
            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = round.briefing;
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new DemandForecastAdapter(), {
            simulationType: 'demand_forecasting',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

})();
